function message(text,error=false){const n=$(error?'error':'message');n.textContent=text;n.hidden=false;}
function clearMessages(){$('error').hidden=true;$('message').hidden=true;}
function protect(d,u){return d.uuid===u||(d.children||[]).some(c=>protect(c,u));}
