function storageTotals(pools){const seen=new Set();let total=0,free=0,count=0,offline=0;for(const p of pools){if(!p.mounted||!Number.isFinite(p.total_bytes)||!Number.isFinite(p.available_bytes)){offline++;continue;}const id=p.filesystem_uuid||p.mountpoint||p.name;if(seen.has(id))continue;seen.add(id);total+=p.total_bytes;free+=p.available_bytes;count++;}return {total,free,used:Math.max(0,total-free),count,offline};}
