function allJobs(){if(familyMember())return (state?.nas.jobs||[]).map(j=>({...j,source:'nas'})).sort((a,b)=>b.created-a.created);return [...(state?.webJobs||[]).map(j=>({...j,source:'console'})),...(state?.nas.jobs||[]).map(j=>({...j,source:'nas'}))].sort((a,b)=>b.created-a.created);}
function jobCards(parent,jobs){if(!jobs.length)empty(parent,'No operations yet.');jobs.forEach(j=>{const a=el('article');a.append(el('h3',({'pool-create':'Create storage','usb-create':'Set up USB storage','config-backup':'Back up settings','media.scan':'Scan media','files.transfer':'Copy / move files','backup.run':'Back up files','backup.restore':'Restore files'})[j.kind]||j.kind.replaceAll(/[.-]/g,' ')),el('span',({succeeded:'Finished',running:'Running',queued:'Waiting',retryable:'Needs attention',failed:'Failed'})[j.status]||j.status,{class:'badge '+(j.status==='succeeded'?'good':j.status==='retryable'?'warn':'')}),el('p',humanTime(j.created)));if(j.error)a.append(el('p',j.error));if(j.result){const details=el('details');details.append(el('summary','Result'),el('pre',typeof j.result==='string'?j.result:JSON.stringify(j.result,null,2)));a.append(details);}a.dataset.jobStatus=j.status;a.classList.add('job-timeline-item',j.status==='failed'?'job-bad':j.status==='succeeded'?'job-good':'job-watch');if(j.status==='retryable'&&(j.source==='console'||['backup.run','backup.system-run','backup.check','media.scan'].includes(j.kind)))a.append(action('Retry this job',async()=>{if(j.source==='nas')await nas('jobs.retry',{id:j.id});else await api('/api/jobs/retry',{id:j.id});await refresh(true);},true,true));parent.append(a);});}
