function describePlan(plan){if(plan.kind==='array-recovery'){describeArrayRecovery(plan);return;}const out=$('review-detail');out.replaceChildren();const b=plan.body||{};if(b.regions){row(out,'Pool',b.name+' · '+b.level);row(out,'Encryption',b.encrypted?'LUKS2':'None');row(out,'Estimated capacity',size(b.usable_bytes_before_overhead));const t=table(['Disk serial','Target partition','Extent','OS partitions']);b.regions.forEach(r=>{const row=el('tr');[r.disk.serial,r.partition,r.start+' → '+r.end,r.os_disk?'Preserved':'Not an OS disk'].forEach(v=>row.append(el('td',v)));t.body.append(row);});out.append(t.wrap,el('p','The listed extents will be formatted. Initial RAID synchronization can take hours.',{class:'notice warning'}));}else Object.entries(b).forEach(([k,v])=>{if(k==='resume')row(out,'Continuation','Reuse and verify the retained partial copy');else if(k!=='review')row(out,k.replaceAll('_',' '),typeof v==='object'?JSON.stringify(v):String(v));});if(b.review)out.append(el('pre',JSON.stringify(b.review,null,2)));}
function confirmTyped(description){return prompt(description+'\nType CONFIRM to continue.')==='CONFIRM';}
function reviewFeedback(text,error=false){const node=$('review-feedback');if(!node)return;node.textContent=text;node.hidden=!text;node.className='notice '+(error?'error':'');node.setAttribute('role',error?'alert':'status');}
