async function getSecret(){if($('secret-method').value==='key'){const file=$('secret-key').files[0];if(file&&(file.size<(['external.unlock','storage.unlock'].includes(currentPlan?.operation)?1:32)||file.size>4096))throw Error('Choose a key file of 32–4096 bytes.');const data=generatedKey||(file?new Uint8Array(await file.arrayBuffer()):null);if(!data)throw Error('Select or generate a key file.');return {key_base64:b64(data)};}const password=$('secret-password').value;if(password.length<(['external.unlock','storage.unlock'].includes(currentPlan?.operation)?1:12))throw Error(['external.unlock','storage.unlock'].includes(currentPlan?.operation)?'Enter the existing disk password.':'Use at least 12 password characters.');if(currentPlan?.plan&&['storage.create','external.create'].includes(currentPlan.operation)&&password!==$('secret-password-confirm').value)throw Error('Passwords do not match.');return {password};}
