function playLibraryMedia(item,lib){const box=$('player');if(!box)return;const ext=item.path.split('.').pop().toLowerCase(),tag=['mp3','flac','m4a','ogg','wav'].includes(ext)?'audio':['jpg','jpeg','png'].includes(ext)?'img':'video',p=el(tag,null,{class:'media-player',src:'/api/file?'+new URLSearchParams({share:lib.share,path:item.path,inline:'1'}),controls:tag==='img'?null:'',preload:'metadata'});box.replaceChildren(el('h3',item.title||item.path),p);p.addEventListener('error',()=>message('This browser cannot play this file. Download it or open it in a compatible media player.',true));if(tag==='video'){box.append(action('Full screen',()=>p.requestFullscreen?.(),false,true));if(document.pictureInPictureEnabled&&p.requestPictureInPicture)box.append(action('Floating video · picture-in-picture',()=>p.requestPictureInPicture(),false,true));box.append(action('Use current frame as cover',async()=>{await nas('media.artwork',{id:item.id,seconds:p.currentTime});await loadCatalog();}));}box.append(action('Share Social',()=>shareSocial({type:'files',share:lib.share,path:item.path},item.path,'/api/file?'+new URLSearchParams({share:lib.share,path:item.path})),false,true));box.append(action('Metadata / EXIF',()=>editFileMetadata({type:'files',share:lib.share,path:item.path}),false,true));box.append(action('Close player',()=>{if(p.pause)p.pause();box.replaceChildren();},false,true));box.scrollIntoView({behavior:'smooth',block:'center'});if(p.play)p.play().catch(()=>message('Press the player’s play button to start playback.'));}

