// Keep status visible while less-used controls remain one click away.
function compactFold(node,label){if(!node||node.closest('details'))return;const d=el('details',null,{class:'compact-fold'});d.append(el('summary',label));node.before(d);d.append(node);return d;}
function compactWorkspace(w,page){
 const foldTitles={storage:['Disk reports & SMART tests','Create storage'],backups:['Console configuration backups','Local NAS configuration backups','Scheduled backups','NAS recovery configuration'],alerts:['Health thresholds','Resolved incidents','Alert rules & sound','Email and browser push','Installable PWA and push devices','Notification transport history'],recovery:['Import and recovery','Restore files & recycle bin','Array checks']};
 for(const p of [...w.querySelectorAll('.panel')]){const title=p.querySelector(':scope > h2')?.textContent;if((foldTitles[page]||[]).includes(title))compactFold(p,title);}
 if(page==='vpn')for(const f of [...w.children].filter(c=>c.tagName==='FORM'))compactFold(f,'VPN client, server & gateway settings');
 if(page==='backups'){const destination=[...w.querySelectorAll('.panel')].find(p=>p.querySelector('h2')?.textContent==='Backup destinations');const form=destination?.querySelector('form');if(form)compactFold(form,'Add a backup destination');}
 if(page==='shares'){const grid=w.querySelector('.two'),existing=[...w.children].find(p=>p.querySelector('h2')?.textContent==='Shared folders');if(grid&&existing){w.prepend(existing);const d=compactFold(grid,'Users & shared folder settings');existing.addEventListener('click',e=>{if(e.target.closest('button')?.textContent==='Edit'&&d){d.open=true;grid.scrollIntoView({behavior:'smooth'});}});}}
 // Explanatory footnotes stay accessible without dominating the first screen.
 for(const note of [...w.querySelectorAll('p.note')])if(note.textContent.length>240&&!note.closest('details')&&!note.id){const d=el('details',null,{class:'compact-help'});d.append(el('summary','About this feature'));note.before(d);d.append(note);}
}

function drawCoolingReadings(out,c){out.replaceChildren();row(out,'Fan mode',c.controller?.attended_trial?'Attended cooling test':c.configured_mode==='auto'?'Automatic':'Full speed');if(c.available){row(out,'Current airflow',c.level===7?'Full speed':'High speed');const v=c.sample;if(v){row(out,'Fans',(v.fans||[]).map(f=>Math.round(f.rpm)+' RPM').join(' · '));row(out,'CPU',v.cpu_c+' °C');row(out,'Disks',(v.disks_c||[]).map(t=>t===null?'Unavailable':t+' °C').join(' · '));}if(c.fault){const messages={'cpu-unavailable-or-stale':'CPU temperature is missing or out of date.','disk-temperature-unavailable-or-stale':'A disk temperature reading is missing or out of date.','fan-feedback-unavailable-or-fault':'A fan is not reporting a normal speed.','automatic-mode-not-accepted-or-guard-unavailable':'Automatic cooling is locked or its safety monitor needs attention.'};out.append(el('p',(messages[c.reason]||'The cooling controller needs attention.')+' Full speed has been requested.',{class:'notice error'}));}}else out.append(el('p','Cooling status is unavailable. Check the NAS and system health.',{class:'notice error'}));const d=c.watchdog||{};row(out,'Hardware watchdog',d.available?(d.state==='active'?'Enabled · '+d.timeout_seconds+' second timeout':d.expected_enabled?'Needs attention · not active':'Off'):'Unavailable');if(d.expected_enabled&&(!d.available||d.state!=='active'))out.append(el('p','Automatic recovery is configured, but the hardware watchdog is not active.',{class:'notice error'}));}
function coolingSettings(w){const c=state.nas.cooling;if(!c)return;const p=panel('Cooling & automatic recovery','Full speed is the safe default. Automatic cooling uses only the tested high-airflow range.'),readings=el('div',null,{id:'cooling-readings',class:'two'});drawCoolingReadings(readings,c);p.append(readings);const controls=el('div',null,{class:'actions'}),automatic=action('Automatic',async()=>{await nas('system.cooling-mode',{mode:'auto'});await refresh(true);});automatic.id='cooling-auto-button';automatic.disabled=!c.automatic_accepted||demo||!nasAvailable;controls.append(action('Full speed',async()=>{await nas('system.cooling-mode',{mode:'full'});await refresh(true);}),automatic);p.append(controls);const acceptanceNote=el('p','Automatic mode will become available after this NAS passes its cooling tests.',{id:'cooling-acceptance-note'});acceptanceNote.hidden=!!c.automatic_accepted;p.append(acceptanceNote);coolingHistoryPanel(p);w.append(p);}
let coolingRefreshBusy=false;
async function updateCoolingReadings(){const out=$('cooling-readings');if(!out||coolingRefreshBusy||demo||document.hidden)return;coolingRefreshBusy=true;try{const c=await nas('system.cooling-status',{});if(!out.isConnected)return;drawCoolingReadings(out,c);const a=$('cooling-auto-button');if(a)a.disabled=!c.automatic_accepted||!nasAvailable;const note=$('cooling-acceptance-note');if(note)note.hidden=!!c.automatic_accepted;}catch{if(out.isConnected){out.replaceChildren(el('p','Cooling status is unavailable. Use the NAS service activity to investigate.',{class:'notice warning'}));if($('cooling-auto-button'))$('cooling-auto-button').disabled=true;}}finally{coolingRefreshBusy=false;}}
setInterval(()=>{if(routeName()==='settings')updateCoolingReadings();},5000);

function coolingHistoryPanel(parent){const d=el('details'),out=el('div',null,{class:'two'}),note=el('p',null,{class:'muted'});d.append(el('summary','Temperature & fan history'),out,note);parent.append(d);let loaded=false;d.addEventListener('toggle',async()=>{if(!d.open){loaded=false;return;}if(loaded)return;loaded=true;out.replaceChildren();try{if(demo){empty(out,'History is available on the running NAS.');return;}const data=await nas('system.cooling-history',{limit:120});for(const [label,key,max]of [['CPU temperature','temperature',80],['Hottest disk','hottest_disk',60],['Fan 1 · RPM','fan0',null],['Fan 2 · RPM','fan1',null],['Fan 3 · RPM','fan2',null]]){const card=el('article',null,{class:'metric-chart-card'}),canvas=el('canvas',null,{role:'img','aria-label':label+' history'});card.append(el('h3',label),canvas);out.append(card);drawMetricChart(canvas,data.points,key,max);}note.textContent=data.stale?'History is stale; use current status above.':'Sampled every 30 seconds. Fan numbers identify counters, not verified physical positions.';note.className=data.stale?'notice warning':'muted';}catch(e){empty(out,e.message);}});}

let fileTransfersBusy=false;
let fileTransferRows=[];
function transferDestination(job){const p=job.paths||{};return typeof p.target_share==='string'&&typeof p.target_path==='string'?{share:p.target_share,path:p.target_path,names:p.target_names||[],published:p.published_names||[]}:null;}
function incomingTransfers(pane){return fileTransferRows.filter(job=>{const d=transferDestination(job);return ['queued','running'].includes(job.status)&&d&&d.share===pane.share&&d.path===pane.path&&d.names.some(name=>!d.published.includes(name));});}
function syncIncomingTransfers(){if(typeof filePanes==='undefined')return;for(const pane of filePanes){const out=$('pane-incoming-'+pane.id);if(!out)continue;out.replaceChildren();for(const job of incomingTransfers(pane)){const d=transferDestination(job),names=d.names.filter(name=>!d.published.includes(name)),note=el('div',null,{class:'notice incoming-copy'});note.append(el('strong','Incoming copy: '+names.join(', ')),action('Appears after verification · View progress',()=>$('file-transfers')?.scrollIntoView({behavior:'smooth',block:'start'}),false,true));out.append(note);}}}
async function openTransferDestination(job){const destination=transferDestination(job);if(!destination)return;let pane=filePanes.find(p=>p.id===fileActive)||filePanes[0];if(!pane){newFileWindow();pane=filePanes.at(-1);}pane.share=destination.share;pane.history=[];pane.minimized=false;const windowNode=$('folder-window-'+pane.id);if(windowNode)windowNode.hidden=false;await navigatePane(pane,destination.path);focusFileWindow(pane);syncIncomingTransfers();}
function transferDuration(seconds){if(!Number.isFinite(seconds))return 'Calculating…';seconds=Math.max(0,Math.round(seconds));return seconds>=3600?Math.floor(seconds/3600)+'h '+Math.ceil(seconds%3600/60)+'m':seconds>=60?Math.floor(seconds/60)+'m '+seconds%60+'s':seconds+'s';}
async function loadFileTransfers(){
 const out=$('file-transfers');if(!out||demo||fileTransfersBusy)return;fileTransfersBusy=true;
 try{
  const r=await nas('files.transfers');if(!out.isConnected)return;fileTransferRows=r.transfers;syncIncomingTransfers();const previous=out.querySelector('.file-transfer-history'),historyOpen=!!previous?.open,previousScroll=previous?.scrollTop||0,expanded=new Set([...out.querySelectorAll('.file-transfer-more')].filter(n=>n.open).map(n=>n.dataset.job));out.replaceChildren();out.append(el('h3','Your file transfers'));
  const active=r.transfers.filter(j=>['queued','running'].includes(j.status)),history=r.transfers.filter(j=>!['queued','running'].includes(j.status)),jobs=[...active,...history].slice(0,8),past=el('details',null,{class:'file-transfer-history'});past.open=historyOpen;past.append(el('summary','Previous transfers ('+history.length+')'));
  if(!jobs.length){out.append(el('small','No file transfers. Copy or move items between folder windows to begin.'));return;}
  for(const j of jobs){const p=j.progress||{},failed=j.status==='retryable',card=el('article',null,{class:'file-transfer-card '+(failed?'failed':j.status==='succeeded'?'complete':'running')}),title=failed?'Copy stopped':j.status==='queued'?'Waiting to start…':j.status==='succeeded'?'Transfer complete':p.phase==='scanning'?'Counting files…':p.phase==='verifying'?'Verifying copied data…':p.phase==='publishing'?'Finishing verified folder…':'Copying files…';card.append(el('strong',title));
   const bar=el('progress',null,{max:100,...(p.percent===null||p.percent===undefined?(failed?{value:0}:{}):{value:p.percent})});card.append(bar);
   const details=el('div',null,{class:'file-transfer-metrics'});for(const [label,value]of [['Progress',failed?'Stopped':p.percent===null||p.percent===undefined?'Counting…':Math.round(p.percent)+'%'],['Copied',size(p.copied_bytes||0)+' / '+(p.totals_ready?size(p.total_bytes):'counting')],['Verified',size(p.verified_bytes||0)],['Speed',p.copy_bytes_per_second?size(p.phase==='verifying'?p.verify_bytes_per_second:p.copy_bytes_per_second)+'/s':'Measuring…'],['Remaining',failed?'Stopped':j.status==='succeeded'?'Finished':p.stale?'Waiting for update':transferDuration(p.eta_seconds)],['Files',p.totals_ready?(p.files_completed||0)+' / '+p.total_files:(p.total_files||0)+' found']]){const m=el('span');m.append(el('small',label),el('b',value));details.append(m);}card.append(details);const more=el('details',null,{class:'file-transfer-more'});more.dataset.job=j.id;more.open=expanded.has(j.id);more.append(el('summary','Paths & transfer details'));card.append(more);if(p.reused_bytes)more.append(el('small','Continuing retained copy · '+size(p.reused_bytes)+' reused. Progress recounts existing files as they are checked; retained data is not discarded.'));const context=j.paths||{};for(const [label,value]of [['From',context.source_file||context.source],['To',context.destination_file||context.destination]])if(value){const line=el('div',null,{class:'file-transfer-path'});line.append(el('small',label),el('span',value));more.append(line);}if(context.sampled_file_at)more.append(el('small','Last active file observed '+new Date(context.sampled_file_at*1000).toLocaleTimeString()+'. Paths update with the system inventory.'));else if(p.current_file)more.append(el('small','Current filename: '+p.current_file));if(context.selections?.length>1)more.append(el('small','Selected: '+context.selections.join(' · ')));more.append(el('small',j.publication));const destination=transferDestination(j);if(destination)more.append(action(j.status==='succeeded'?'Open completed destination':'Open destination folder',()=>openTransferDestination(j),false,true));
   if(failed){card.append(el('p',/Operation not permitted/.test(j.error||'')?'Copy was blocked by a permission check. Source files and completed copies were retained.':j.error||'The transfer stopped; completed files and source data are retained.',{class:'notice warning'}));const resume=action('Continue partial copy…',async()=>reviewPlan(await nas('files.transfer-resume-plan',{id:j.id}),'files.transfer'),true,true),again=action('Start a new copy…',async()=>reviewPlan(await nas('files.transfer-retry-plan',{id:j.id}),'files.transfer'),true,true);for(const button of [resume,again])button.disabled=button.disabled||!canPersonal('files.write')||r.transfers.some(v=>['queued','running'].includes(v.status));card.append(resume,again);}if(['queued','running'].includes(j.status)||!active.length&&j===jobs[0])out.append(card);else past.append(card);
  }
  if(past.children.length>1){out.append(past);past.scrollTop=previousScroll;}
 }catch(e){if(out.isConnected){out.replaceChildren(el('p','Transfer status unavailable: '+e.message,{class:'notice warning'}));}}finally{fileTransfersBusy=false;}
}
